{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울시 조례상 자전거 안전교육에 주차질서 내용 포함 요구 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울시 조례는 자전거 안전교육에 주차질서 내용을 포함하도록 요구하고 있습니다. 다만 이는 의무(하여야 한다)가 아니라 시장의 노력 의무(노력하여야 한다)로 규정되어 있습니다. 원문 제13조제7항은 시장이 자전거 주차질서 확립 및 무단 주차 예방과 관련된 내용을 자전거 교통안전교육에 포함하도록 노력하여야 한다고 정하고 있습니다.",
          "b_ids": "자전거:제13조제7항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
